import{_ as t,C as o,o as l,c as s,a2 as r,E as n}from"./chunks/framework.TaNiW7i8.js";const g=JSON.parse('{"title":"Aide","description":"","frontmatter":{"title":"Aide"},"headers":[],"relativePath":"guide/help.md","filePath":"guide/help.md"}'),i={name:"guide/help.md"};function u(d,e,p,h,c,m){const a=o("Capture");return l(),s("div",null,[e[0]||(e[0]=r('<h1 id="aide" tabindex="-1">Aide <a class="header-anchor" href="#aide" aria-label="Permalink to &quot;Aide&quot;">​</a></h1><p>L&#39;aide de Kessho est une fenêtre qui présente quelques-uns des outils que vos agents d&#39;IA peuvent appeler dans la mémoire. Elle s&#39;ouvre depuis la barre latérale, par-dessus l&#39;écran en cours, et ne change rien dans votre mémoire.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>Cliquez <strong>Aide</strong> en bas de la barre latérale, à côté de <strong>Réglages</strong>. La fenêtre <strong>Centre d&#39;Aide &amp; Outils MCP Kessho</strong> s&#39;ouvre.</p><ul><li><strong>Le titre et son sous-titre</strong> : « Catalogue des outils exposés par le serveur MCP embarqué ».</li><li><strong>Le champ de recherche</strong> : « Rechercher un outil MCP (ex: mem_recall, health)... ».</li><li><strong>Les familles</strong>, sous forme de pastilles : <strong>Tous</strong>, <strong>Mémoire &amp; Rappel</strong>, <strong>Santé &amp; Intégrité</strong>, <strong>Connecteurs CLI</strong> et <strong>Gouvernance</strong>.</li><li><strong>La liste des outils</strong> : pour chacun, son nom, sa famille, une phrase qui dit à quoi il sert et un exemple d&#39;appel (« Usage: … », tel qu&#39;affiché).</li><li><strong>Un bouton ✕</strong>, en haut à droite, pour fermer.</li></ul><p>Cette liste est un aperçu : une dizaine d&#39;outils, pas tous. La liste complète et à jour se trouve dans la <a href="/Kessho/reference/mcp/">référence MCP</a>.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="ouvrir-l-aide" tabindex="-1">Ouvrir l&#39;aide <a class="header-anchor" href="#ouvrir-l-aide" aria-label="Permalink to &quot;Ouvrir l&#39;aide&quot;">​</a></h3><p>Cliquez <strong>Aide</strong> dans la barre latérale. Quand la barre est repliée, le bouton garde son icône (un point d&#39;interrogation) et son infobulle <strong>Aide</strong>.</p><h3 id="chercher-un-outil" tabindex="-1">Chercher un outil <a class="header-anchor" href="#chercher-un-outil" aria-label="Permalink to &quot;Chercher un outil&quot;">​</a></h3><p>Tapez dans le champ de recherche. La liste se réduit aux outils dont le nom ou la description contient votre texte, sans tenir compte des majuscules. Si rien ne correspond, la fenêtre dit « Aucun outil MCP ne correspond à votre recherche. »</p>',11)),n(a,{name:"aide",alt:"Le Centre d'Aide et outils MCP : le catalogue des outils exposés aux agents, filtré par la saisie « health »."}),e[1]||(e[1]=r('<h3 id="filtrer-par-famille" tabindex="-1">Filtrer par famille <a class="header-anchor" href="#filtrer-par-famille" aria-label="Permalink to &quot;Filtrer par famille&quot;">​</a></h3><p>Cliquez une famille pour ne garder que ses outils ; <strong>Tous</strong> les remontre. La recherche et la famille se combinent.</p><h3 id="fermer-la-fenetre" tabindex="-1">Fermer la fenêtre <a class="header-anchor" href="#fermer-la-fenetre" aria-label="Permalink to &quot;Fermer la fenêtre&quot;">​</a></h3><p>Cliquez le <strong>✕</strong>, ou cliquez à côté de la fenêtre, sur le fond.</p><h3 id="aller-plus-loin" tabindex="-1">Aller plus loin <a class="header-anchor" href="#aller-plus-loin" aria-label="Permalink to &quot;Aller plus loin&quot;">​</a></h3><ul><li>Pour apprendre à demander ces outils à un agent, voir <a href="/Kessho/guide/agents.html">Connecter ses agents</a>.</li><li>Pour le détail de chaque outil, ses paramètres et des exemples, voir la <a href="/Kessho/reference/mcp/">référence MCP</a>.</li></ul>',6))])}const q=t(i,[["render",u]]);export{g as __pageData,q as default};
